<?php require_once __DIR__.'/includes/functions.php';if(empty($_SESSION['two_factor_challenge'])){header('Location: '.BASE_URL.'login.php');exit;}$page_title='ยืนยันสองขั้นตอน';require_once __DIR__.'/includes/header.php';?><link rel="stylesheet" href="<?php echo BASE_URL;?>assets/css/auth.css"><div class="auth-page"><section class="auth-shell"><aside class="auth-intro"><p class="eyebrow">TWO-STEP VERIFICATION</p><h1>ยืนยันว่าเป็นคุณ</h1><p>เราได้ส่งรหัส 6 หลักไปยังอีเมลของบัญชี รหัสจะหมดอายุภายใน 10 นาที</p></aside><div class="auth-card"><header class="auth-heading"><h2>กรอกรหัสยืนยัน</h2></header><div class="auth-error" id="authError"><span></span></div><form class="auth-form" id="twoFactorForm"><div class="auth-field"><label>รหัส 6 หลัก</label><div class="auth-input"><i class="fa-solid fa-shield-halved"></i><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required autofocus></div></div><input type="hidden" name="action" value="verify_2fa"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><button class="btn btn-primary auth-submit">ยืนยันเข้าสู่ระบบ</button></form></div></section></div><script>document.getElementById('twoFactorForm').onsubmit=async e=>{e.preventDefault();const r=await fetch(`${BASE_URL}api/auth.php`,{method:'POST',body:new FormData(e.currentTarget)}),j=await r.json();if(j.status==='success')location.href=j.data.redirect;else{const b=document.getElementById('authError');b.querySelector('span').textContent=j.message;b.classList.add('show')}};</script><?php require_once __DIR__.'/includes/footer.php';?>
